import React, { useEffect, useState } from 'react';
import {
  Avatar,
  Box,
  Button,
  Divider,
  TextField,
  Typography,
} from '@mui/material';
import { useForm } from 'react-hook-form';
import MinimalAppBar from '../../Component/MinimalAppBar';
import { useNavigate } from 'react-router-dom';
import { useUser } from '../../Context/userContext';

type ProfileForm = {
  fullName: string;
  email: string;
  avatar: FileList;
  currentPassword: string;
  newPassword: string;
  confirmPassword: string;
};


let profile: ProfileForm | null = null;

try {
  const storedProfile = localStorage.getItem('profile');
  if (storedProfile) {
    profile = JSON.parse(storedProfile) as ProfileForm;
  }
} catch (error) {
  console.error('Error parsing profile:', error);
}


const ProfileScreen: React.FC = () => {

  const navigate = useNavigate();

  const {
    register,
    handleSubmit,
    watch,
    setValue,
    reset,
    formState: { errors },
  } = useForm<ProfileForm>();
  const [avatarPreview, setAvatarPreview] = useState<string | null>(null);
  const {user} = useUser();
  useEffect(() => {
    if (profile) {
      reset(profile);
    }
  }, [reset]);

  useEffect(() => {
    return () => {
      if (avatarPreview) {
        URL.revokeObjectURL(avatarPreview);
      }
    };
  }, [avatarPreview]);


  const handleAvatarChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setAvatarPreview(URL.createObjectURL(file));
    }
  };

  const onSubmit = (data: ProfileForm) => {
    if (data.newPassword && data.newPassword !== data.confirmPassword) {
      alert('รหัสผ่านใหม่ไม่ตรงกัน');
      return;
    }

    console.log('Profile updated:', data);
    // TODO: Upload avatar, update profile, and change password via API
  };


  const handleLogout = () => {
    localStorage.removeItem('profile');
    localStorage.removeItem('token');
    navigate('/login');
  };


  return (
    <>
      <MinimalAppBar onBack={() => window.history.back()} title="โปรไฟล์ผู้ใช้" />
      <Box p={3}>
        <Box display="flex" flexDirection="column" alignItems="center" mb={2}>
          <Avatar
            src={user?.imageUrl || '/default-avatar.png'}
            sx={{ width: 100, height: 100, mb: 1 }}
          />
          <Button variant="outlined" component="label">
            เปลี่ยนรูปโปรไฟล์
            <input
              type="file"
              hidden
              accept="image/*"
              {...register('avatar')}
              onChange={handleAvatarChange}
            />
          </Button>
        </Box>

        <form onSubmit={handleSubmit(onSubmit)}>
          <TextField
            disabled
            label="ชื่อ-นามสกุล"
            fullWidth
            margin="normal"
            {...register('fullName', { required: 'กรุณากรอกชื่อ' })}
            error={!!errors.fullName}
            helperText={errors.fullName?.message}
          />

          <TextField
            disabled
            label="อีเมล"
            fullWidth
            margin="normal"
            {...register('email', {
              required: 'กรุณากรอกอีเมล',
              pattern: {
                value: /^\S+@\S+$/i,
                message: 'รูปแบบอีเมลไม่ถูกต้อง',
              },
            })}
            error={!!errors.email}
            helperText={errors.email?.message}
          />

          <Divider sx={{ my: 3 }} />

          <Typography variant="subtitle1" gutterBottom>
            เปลี่ยนรหัสผ่าน
          </Typography>

          <TextField
            label="รหัสผ่านปัจจุบัน"
            type="password"
            fullWidth
            margin="normal"
            {...register('currentPassword')}
          />

          <TextField
            label="รหัสผ่านใหม่"
            type="password"
            fullWidth
            margin="normal"
            {...register('newPassword', {
              minLength: {
                value: 8,
                message: 'รหัสผ่านต้องมีอย่างน้อย 8 ตัวอักษร',
              },
            })}
            error={!!errors.newPassword}
            helperText={errors.newPassword?.message}
          />

          <TextField
            label="ยืนยันรหัสผ่านใหม่"
            type="password"
            fullWidth
            margin="normal"
            {...register('confirmPassword')}
          />

          <Button type="submit" variant="contained" color="primary" sx={{ mt: 3 }}>
            บันทึกข้อมูล
          </Button>
        </form>

        <Divider sx={{ my: 4 }} />

        <Button variant="outlined" color="error" fullWidth onClick={handleLogout}>
          ออกจากระบบ
        </Button>
      </Box>
    </>
  );
};

export default ProfileScreen;
